/* @autogenerated */
import { Directive, inject } from '@angular/core';
import { takeUntilDestroyed } from '@angular/core/rxjs-interop';
import { endWith, ignoreElements, Observable, of, Subscription, switchMap } from 'rxjs';
import { ConfirmDialogService } from '../dialog/confirm-dialog.service';
import { NotifyService } from '../notify/notify.service';
import { BaseAction } from './base-action';

/**
 * Acción que pide confirmación, ejecuta `execute(items)`, avisa del resultado y cierra el contenedor.
 *
 * Textos (`<scope>.action.<textKey>.*`): `title`, `content`, `okBtn`, `cancelBtn`, `report`, `dismiss`.
 */
@Directive()
export abstract class ConfirmAction<T = any> extends BaseAction<T> {
  private readonly confirmDialog = inject(ConfirmDialogService);
  private readonly notify = inject(NotifyService);
  private pending?: Subscription;

  protected abstract execute(items: T[]): Observable<unknown>;

  run(): void {
    const items = this.selection();
    // Cancelar la suscripción cierra el diálogo que siguiera abierto
    this.pending?.unsubscribe();
    this.pending = this.confirmDialog
      .confirm({
        messageKey: this.textKeyOf('content') ?? 'common.action.content',
        titleKey: this.textKeyOf('title'),
        okKey: this.textKeyOf('okBtn'),
        cancelKey: this.textKeyOf('cancelBtn'),
      })
      .pipe(
        switchMap((ok) => (ok ? this.execute(items).pipe(ignoreElements(), endWith(true)) : of(false))),
        takeUntilDestroyed(this.destroyRef),
      )
      .subscribe((done) => {
        this.container()?.close();
        if (done) {
          this.notify.success(this.textKeyOf('report') ?? 'common.action.report', undefined, this.textKeyOf('dismiss'));
        }
      });
  }
}
